arguments.command:
python3 - <<'EOF'
import json
d=json.load(open('/workspace/examples.json'))
for ex in d:
    print('=== name:', ex['name'])
    print(json.dumps(ex['request'], indent=1))
    if 'expected' in ex:
        print('--- expected:')
        print(json.dumps(ex.get('expected'), indent=1))
    for k in ex:
        if k not in ('name','request','expected'):
            print('--- other key', k, ':', json.dumps(ex[k])[:2000])
EOF
